package com.johnny.hotel.extras;import com.johnny.hotel.entity.FolioItem;import com.johnny.hotel.exception.BusinessException;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Component;import java.util.*;import static com.johnny.hotel.service.support.BillingRules.require;
@Component@RequiredArgsConstructor public class ExtrasLedgerRules{private final ExtrasMapper db;public List<FolioItem> validate(Long folio,List<FolioItem> ledger){var accounted=new HashSet<Long>();for(var o:db.servicesForFolio(folio)){if(o.getStatus()==0||o.getStatus()==1)throw new BusinessException("Pending guest services must be completed or cancelled before checkout");if(o.getStatus()==3){require(o.getFolioItemId()==null,"Cancelled service cannot have a charge");continue;}var item=ledger.stream().filter(i->Objects.equals(i.getId(),o.getFolioItemId())).findFirst().orElse(null);require(item!=null&&accounted.add(item.getId())&&"GUEST_SERVICE_ORDER".equals(item.getSourceType())&&Objects.equals(item.getSourceId(),o.getId())&&"SERVICE_CHARGE".equals(item.getItemType())&&item.getAmount().compareTo(o.getAmount())==0&&item.getQuantity().compareTo(o.getQuantity())==0&&item.getUnitPrice().compareTo(o.getUnitPriceSnapshot())==0&&Objects.equals(item.getDescription(),o.getNameSnapshot()),"Completed service does not match its Folio item");}
 var purchases=db.purchasesForFolio(folio);var lines=db.purchaseItemsForFolio(folio);for(var p:purchases){var own=lines.stream().filter(i->i.getPurchaseId().equals(p.getId())).toList();if(p.getStatus()==0)throw new BusinessException("Pending purchases must be confirmed or cancelled before checkout");if(p.getStatus()==2){require(own.stream().allMatch(i->i.getFolioItemId()==null),"Cancelled purchase cannot have charges");continue;}for(var x:own){var item=ledger.stream().filter(i->Objects.equals(i.getId(),x.getFolioItemId())).findFirst().orElse(null);require(item!=null&&accounted.add(item.getId())&&"GUEST_PURCHASE_ITEM".equals(item.getSourceType())&&Objects.equals(item.getSourceId(),x.getId())&&"SERVICE_CHARGE".equals(item.getItemType())&&item.getAmount().compareTo(x.getAmount())==0&&item.getQuantity().compareTo(x.getQuantity())==0&&item.getUnitPrice().compareTo(x.getUnitPriceSnapshot())==0&&Objects.equals(item.getDescription(),x.getNameSnapshot()),"Confirmed purchase does not match its Folio item");}}
 return ledger.stream().filter(i->!accounted.contains(i.getId())).toList();}}
